<script lang="ts">import { portalState,year } from '$lib/stores/portal';import { tr,lang } from '$lib/stores/lang';import { rankedContributors,downloadsForPerson } from '$lib/api/derive';import { safeUrl } from '$lib/utils/format';import { Download } from '@lucide/svelte';let people=$derived(rankedContributors($portalState.data,$year));</script><svelte:head><title>{$tr('download_center')} — {$tr('app_title')}</title></svelte:head><div class="kinetic-command"><div class="kinetic-kicker">05 / DOCUMENT ARCHIVE</div><h1 class="kinetic-title">Downloads.</h1></div><p class="kinetic-subtitle">Receipts, certificates and consent documents — indexed from the public ledger.</p><div class="kinetic-list">{#each people as entry,i}{@const docs=downloadsForPerson($portalState.data,entry.item.key)}<article class="kinetic-panel"><div class="kinetic-row" style="border-top:0;padding-top:0"><div class="kinetic-index">{i+1}</div><div><div class="kinetic-name">{$lang==='hi'&&entry.item.nameHindi?entry.item.nameHindi:entry.item.name}</div><div class="kinetic-micro">{docs.reduce((n,g)=>n+g.docs.length,0)} DOCUMENTS</div></div><Download/></div>{#if docs.length}<div class="kinetic-grid kinetic-grid--3" style="margin-top:12px">{#each docs as group}<div><div class="kinetic-label">{$tr(group.titleKey)}</div>{#each group.docs as doc}<a class="kinetic-button kinetic-button--yellow" style="margin-top:7px;width:100%" href={safeUrl(doc.publicLink)||undefined} target="_blank" rel="noopener noreferrer">{doc.year} ↗</a>{/each}</div>{/each}</div>{:else}<div class="kinetic-micro" style="margin-top:10px">{$tr('no_docs')}</div>{/if}</article>{/each}</div>
